        nonempty = [idx for idx, r in enumerate(routes) if r]
        if not nonempty:
            return sol

        # Prefer an inter-route swap when possible; otherwise do an intra-route swap.
        if len(nonempty) >= 2:
            r1, r2 = rng.sample(nonempty, 2)
            route1 = routes[r1]
            route2 = routes[r2]

