        r = nonempty[0]
        route = routes[r]
        if len(route) < 2:
            return sol

        i, j = rng.sample(range(len(route)), 2)
        route[i], route[j] = route[j], route[i]
        return canonical(tuple(tuple(r_) for r_ in routes))


